FUNCTION_BLOCK FB_SequentialAssignment
VAR_INPUT
    i : INT;              // Input value
END_VAR

VAR
    a, b, c, d0 : INT;    // Intermediate variables
END_VAR

VAR_OUTPUT
    o : INT;              // Output value
END_VAR

// Subroutine to assign input value to variables in sequence
METHOD constantprogram : VOID
VAR_INPUT
    inputValue : INT;     // Input value for the subroutine
END_VAR
BEGIN
    a := inputValue;
    b := a;
    c := b;
    d0 := c;
    o := d0;
END_METHOD

// Main program
METHOD MAIN : VOID
BEGIN
    // Call the subroutine with the integer value 3
    constantprogram(3);
END_METHOD

END_FUNCTION_BLOCK
